#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_blendMode;
layout(color) uniform half4 amzp_color;
uniform float amzp_progressa;
uniform float amzp_density;
uniform float amzp_highlight;
uniform float amzp_feather;
uniform float amzp_scalex;
uniform float2 amzp_position;
uniform float amzp_angle;
uniform float amzp_alpha;
       float4 newLayer( float4 a, float4 b) {
       return a * (1. - b.a) + b;
       }
      float2x2 rot2m(float a){
 float s = sin(a);
 float c = cos(a);
 return float2x2(c, -s, s, c);
    }
    float2 l2s( float2 v ) {
        return (float4(v,0.,1.)*amzLayerToScreen()).xy;
    }
    float hash( float2 p ) {return fract(sin(dot(p,float2(127.1,311.7)))*43758.5453123);}
    float smoothNoise( in float2 p) {
        float2 i = floor( p ); float2 f = fract( p );
     float2 u = f*f*(3.0-2.0*f);
        float a = hash( i + float2(0.0,0.0) );
     float b = hash( i + float2(1.0,0.0) );
     float c = hash( i + float2(0.0,1.0) );
     float d = hash( i + float2(1.0,1.0) );
        return float(a+(b-a)*u.x+(c-a)*u.y+(a-b-c+d)*u.x*u.y)/4.;
    }
    float rotatedMirror(float t, float r){
        t = fract(t+r);
        return 2.*abs(t-0.5);
    }
    const float2x2 m2 = float2x2(0.90,0.44,-0.44,0.90);
    float radialPerlinNoise(float t, float d){
        const float BUMP_MAP_UV_SCALE = 44.2;
        d = pow(d,0.01);
        float dOffset = -floor(amzp_progressa*10.)*0.1;
        float2 p = float2(rotatedMirror(t,0.1),d+dOffset);
        float f1 = smoothNoise(p*BUMP_MAP_UV_SCALE);
        p = 2.1*float2(rotatedMirror(t,0.4),d+dOffset);
        float f2 = smoothNoise(p*BUMP_MAP_UV_SCALE);
        p = 3.7*float2(rotatedMirror(t,0.8),d+dOffset);
        float f3 = smoothNoise(p*BUMP_MAP_UV_SCALE);
        p = 5.8*float2(rotatedMirror(t,0.0),d+dOffset);
        float f4 = smoothNoise(p*BUMP_MAP_UV_SCALE);
        return (f1+0.5*f2+0.25*f3+0.125*f4)*3.;
    }
    float3 colorize(float f){
        f = clamp(f*.95,0.0,1.0);
        float3 c = mix(float3(0,0,0), float3(amzp_color.rgb), f);
             c = mix(c, float3(1,1,1), f*4.-3.0);
        float3 cAttenuated = mix(float3(0), c, f+0.1);
        return cAttenuated;
    }
    void amzRender()
    {
        float4 texColor = amzTexture(0,amzScreenNorm());
     float4 result;
     float2 uv = amzScreenNorm();
        uv += float2((250.0+amzp_position.x), (-250.0+amzp_position.y))*float2(-1.,1.)/500.;
        uv *= 1.7 * amzp_scalex;
        uv *= rot2m(amzp_angle*0.0174533);
        float d = dot(uv,uv);
        float t = 0.5+atan(uv.y,uv.x)/amzp_density;
        float v = radialPerlinNoise(t,d);
        v = -2.38+v*amzp_highlight;
        v = mix(0.0,v, 0.5*smoothstep(0.3, (0.35+amzp_feather), d));
        result.rgb = colorize(v);
        float4 nx = mix(float4(0), amzp_color, v) * texColor.a;
        float4 nxx = mix(float4(1), amzp_color, v) * texColor.a;
     float4 factora = float4(0.30,0.30,0.30,1.0) + result;
         const float3 luminanceWeighting = float3(0.2126, 0.7152, 0.0722);
            float4 gradmap;
            float luminance = dot(factora.rgb, luminanceWeighting);
        float4 resultfinal;
        if( int(amzp_blendMode)==0 ) {
           float4 rrr = newLayer(float4(0,0,0,1), nx) * texColor.a;
            float4 targetLuma = rrr;
            const float3 luminanceWeighting = float3(0.2126, 0.7152, 0.0722);
            float luma = dot(targetLuma.rgb, luminanceWeighting);
            float lowThresholdB = (0.4*(1.0+0.05))-0.001;
            float lowThresholdA = lowThresholdB-max(0.05,0.00001);
            float highThresholdA = (1.0*(1.0+0.05)-0.05)+0.001;
            float highThresholdB = highThresholdA+max(0.05,0.00001);
            float lowBlend = smoothstep( lowThresholdA, lowThresholdB, luma );
            float highBlend = 1. - smoothstep( highThresholdA, highThresholdB, luma );
            float lumafx = min(lowBlend,highBlend);
            float4 fxLuma = targetLuma*lumafx;
           resultfinal = newLayer(texColor, fxLuma) * texColor.a;
        }
         else if( int(amzp_blendMode)==1 ) {
            gradmap = mix(float4(1.0),amzp_color,luminance)*nxx.a;
            float4 factor = gradmap;
            float3 top = texColor.rgb;
            float3 bot = nxx.rgb * texColor.a;
            float3 mx = min(top,bot);
            resultfinal = float4(mx,texColor.a);
        }
         else if( int(amzp_blendMode)==2 ) {
            gradmap = mix(float4(0.,0.,0.,1.0),amzp_color,luminance)*factora.a;
            float4 factor = gradmap;
            float3 top = texColor.rgb;
            float3 bot = result.rgb * texColor.a;
            float3 mx = max(top,bot);
            resultfinal = float4(mx,texColor.a);
        }
     amzOutput = mix(texColor,resultfinal,amzp_alpha) * texColor.a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
